// Wrap wraps text into lines of at most `width` characters, breaking only at spaces.
func Wrap(text string, width int) []string {
	if width <= 0 {
		return nil
	}

	fields := strings.Fields(text)
	if len(fields) == 0 {
		return nil
	}

	var lines []string
	var currentLine string

	for _, word := range fields {
		if currentLine == "" {
			currentLine = word
		} else if len(currentLine)+1+len(word) <= width {
			currentLine += " " + word
		} else {
			lines = append(lines, currentLine)
			currentLine = word
		}
	}
	lines = append(lines, currentLine)
	return lines
}

