package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name string
		text string
		width int
		want []string
	}{
		{
			name:  "empty string",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace only",
			text:  "   ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word shorter than width",
			text:  "hello",
			width: 10,
			want:  []string{"hello"},
		},
		{
			name:  "single word longer than width",
			text:  "supercalifragilistic",
			width: 5,
			want:  []string{"supercalifragilistic"},
		},
		{
			name:  "multiple words fit on one line",
			text:  "hello world",
			width: 20,
			want:  []string{"hello world"},
		},
		{
			name:  "multiple words wrap",
			text:  "hello world foo bar",
			width: 10,
			want:  []string{"hello", "world foo", "bar"},
		},
		{
			name:  "collapsed whitespace",
			text:  "  hello    world  ",
			width: 10,
			want:  []string{"hello", "world"},
		},
		{
			name:  "zero width",
			text:  "hello",
			width: 0,
			want:  nil,
		},
		{
			name:  "negative width",
			text:  "hello",
			width: -5,
			want:  nil,
		},
		{
			name:  "word exactly fits width",
			text:  "hello world",
			width: 11,
			want:  []string{"hello world"},
		},
		{
			name:  "word just over width boundary",
			text:  "hello world",
			width: 6,
			want:  []string{"hello", "world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if !equal(got, tt.want) {
				t.Errorf("Wrap(%q, %d) = %v, want %v", tt.text, tt.width, got, tt.want)
			}
		})
	}
}

func equal(a, b []string) bool {
	if a == nil && b == nil {
		return true
	}
	if (a == nil) != (b == nil) {
		return false
	}
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
